588	    /// Describe the disagreement between the outer signatureAlgorithm and the
589	    /// copy inside tbsCertificate. Both copies parse on their own; they merely
590	    /// fail to name the same algorithm or the same parameter representation.
591	    fn mismatch_message(outer: &SignatureAlgorithm<'_>, inner: &SignatureAlgorithm<'_>) -> String {
592	        const OUTER: &str = "the outer signatureAlgorithm";
593	        const INNER: &str = "the signatureAlgorithm in tbsCertificate";
594	        if outer.oid_content != inner.oid_content {
595	            let outer_oid = parse_oid(outer.oid_content)
596	                .map(|arcs| arcs_to_string(&arcs))
597	                .unwrap_or_else(|_| "?".to_string());
598	            let inner_oid = parse_oid(inner.oid_content)
599	                .map(|arcs| arcs_to_string(&arcs))
600	                .unwrap_or_else(|_| "?".to_string());
601	            return format!(
602	                "signature algorithm mismatch: {OUTER} names OID {outer_oid}, but {INNER} \
603	                 names OID {inner_oid}"
604	            );
605	        }
606	        match (outer.params, inner.params) {
607	            (Some(outer_params), Some(inner_params)) if outer_params != inner_params => {
608	                format!(
609	                    "signature algorithm mismatch: both copies name the same algorithm OID but \
610	                     their parameters have different DER encodings ({OUTER} has {}, {INNER} has {})",
611	                    hex_of(outer_params),
612	                    hex_of(inner_params),
613	                )
614	            }
615	            (Some(_), None) => format!(
616	                "signature algorithm mismatch: {OUTER} carries parameters but {INNER} omits them \
617	                 (an absent parameter and an explicit value are different representations)"
618	            ),
619	            (None, Some(_)) => format!(
620	                "signature algorithm mismatch: {INNER} carries parameters but {OUTER} omits them \
621	                 (an absent parameter and an explicit value are different representations)"
622	            ),
623	            // PartialEq already proved the copies unequal; reaching any other
624	            // arm here would be a logic error rather than a malformed cert.
625	            _ => "signature algorithm mismatch between the two signatureAlgorithm copies"
626	                .to_string(),
627	        }
628	    }
