638	    /// Validate the DER content of a BIT STRING: one leading byte counting
639	    /// unused bits (0..=7), and when the count is nonzero those low bits of
640	    /// the final data byte must all be zero. An empty bit string is only
641	    /// legal with a zero count.
642	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
643	        let unused = *content
644	            .first()
645	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
646	        if unused > 7 {
647	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
648	        }
649	        let data = &content[1..];
650	        if data.is_empty() {
651	            if unused != 0 {
652	                return Err(format!(
653	                    "{what} BIT STRING declares {unused} unused bits but has no data"
654	                ));
655	            }
656	            return Ok(());
657	        }
658	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
659	            return Err(format!(
660	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
661	            ));
662	        }
663	        Ok(())
664	    }
