809	    /// Uppercase hex of one complete value TLV, sliced straight from the
810	    /// input bytes (`around` ends at `rest`). The original tag and length
811	    /// bytes survive verbatim, including a legal long-form length; nothing is
812	    /// re-encoded and content alone is never emitted.
813	    fn value_hex(around: &[u8], rest: &[u8]) -> String {
814	        let tlv_len = around.len() - rest.len();
815	        let mut hex = String::with_capacity(tlv_len * 2);
816	        for b in &around[..tlv_len] {
817	            write!(hex, "{b:02X}").unwrap();
818	        }
819	        hex
820	    }
