1018	    /// Whether every byte belongs to the RFC 5280 PrintableString alphabet:
1019	    /// A-Z, a-z, 0-9, space, and ' ( ) + , - . / : = ?. Every other byte
1020	    /// (including @, _, tabs, newlines, NUL and 0x80..=0xFF) is illegal.
1021	    /// An empty value passes, preserving the existing acceptance of empty
1022	    /// contents.
1023	    fn is_printable_string(content: &[u8]) -> bool {
1024	        content.iter().all(|&b| matches!(
1025	            b,
1026	            b'A'..=b'Z'
1027	                | b'a'..=b'z'
1028	                | b'0'..=b'9'
1029	                | b' '
1030	                | b'\''
1031	                | b'('
1032	                | b')'
1033	                | b'+'
1034	                | b','
1035	                | b'-'
1036	                | b'.'
1037	                | b'/'
1038	                | b':'
1039	                | b'='
1040	                | b'?'
1041	        ))
1042	    }
1043	
1044	    /// Validate BMPString content and decode it to UTF-8 text in one pass: an
1045	    /// even number of bytes read as big-endian 16-bit characters, each of
1046	    /// which must be a Basic Multilingual Plane code point
1047	    /// (U+0000..=U+FFFF) and never a UTF-16 surrogate (U+D800..=U+DFFF).
1048	    /// Surrogates are not characters, so a lone high or low surrogate is
1049	    /// corrupt, and so is an adjacent pair that UTF-16 rules would combine
1050	    /// into an astral-plane character — the pair must not be merged and
1051	    /// displayed. An illegal value fails the whole certificate; bytes are
1052	    /// never dropped or replaced to salvage it. Empty content stays legal,
1053	    /// preserving the existing acceptance of empty values. `what` names the
1054	    /// name being checked ("subject"/"issuer") so the error identifies the
1055	    /// offending name.
1056	    fn decode_bmp_string(content: &[u8], what: &str) -> Result<String, String> {
1057	        if content.len() % 2 != 0 {
1058	            return Err(format!(
1059	                "{what} name: BMPString attribute value has an odd length of {} byte(s) \
1060	                 (the content must be a sequence of 16-bit characters)",
1061	                content.len()
1062	            ));
1063	        }
1064	        // A BMPString character is one big-endian 16-bit BMP code point, never
1065	        // a UTF-16 surrogate: surrogate pairs must not be merged into
1066	        // astral-plane characters.
1067	        let mut s = String::with_capacity(content.len() / 2);
1068	        for pair in content.chunks_exact(2) {
1069	            let unit = u16::from_be_bytes([pair[0], pair[1]]);
1070	            if (0xD800..=0xDFFF).contains(&unit) {
1071	                return Err(format!(
1072	                    "{what} name: BMPString attribute value contains the surrogate code \
1073	                     point U+{unit:04X}, which is not a legal character (U+D800..=U+DFFF \
1074	                     are not characters and cannot appear, alone or in pairs)"
1075	                ));
1076	            }
1077	            // Not a surrogate, so every 16-bit unit is a valid scalar value.
1078	            s.push(char::from_u32(unit as u32).unwrap());
1079	        }
1080	        Ok(s)
1081	    }
