1083	    /// Validate UniversalString content and decode it to UTF-8 text in one
1084	    /// pass: the bytes must form whole big-endian 32-bit Unicode code points,
1085	    /// so the length must be a multiple of four, and every code point must lie
1086	    /// in U+0000..=U+10FFFF and never be a UTF-16 surrogate
1087	    /// (U+D800..=U+DFFF). A trailing incomplete unit, a lone surrogate (or a
1088	    /// pair that UTF-16 rules would combine), or a value above the Unicode
1089	    /// ceiling is corrupt; the whole certificate fails and no unit is dropped,
1090	    /// replaced or merely hex-displayed to salvage it. Empty content stays
1091	    /// legal, preserving the existing acceptance of empty values. `what` names
1092	    /// the name being checked ("subject"/"issuer") so the error identifies the
1093	    /// offending name.
1094	    fn decode_universal_string(content: &[u8], what: &str) -> Result<String, String> {
1095	        if content.len() % 4 != 0 {
1096	            return Err(format!(
1097	                "{what} name: UniversalString attribute value has a length of {} byte(s), \
1098	                 which is not a multiple of four (the content must be a sequence of \
1099	                 big-endian 32-bit Unicode code points)",
1100	                content.len()
1101	            ));
1102	        }
1103	        let mut s = String::new();
1104	        for unit in content.chunks_exact(4) {
1105	            let cp = u32::from_be_bytes([unit[0], unit[1], unit[2], unit[3]]);
1106	            if (0xD800..=0xDFFF).contains(&cp) {
1107	                return Err(format!(
1108	                    "{what} name: UniversalString attribute value contains the surrogate code \
1109	                     point U+{cp:04X}, which is not a legal character (U+D800..=U+DFFF are \
1110	                     not characters and cannot appear, alone or in pairs)"
1111	                ));
1112	            }
1113	            if cp > 0x10FFFF {
1114	                return Err(format!(
1115	                    "{what} name: UniversalString attribute value contains the code point \
1116	                     U+{cp:04X}, which is above the Unicode maximum U+10FFFF"
1117	                ));
1118	            }
