1128	    /// (valid UTF-8, the PrintableString alphabet, whole BMP characters
1129	    /// without surrogates, whole in-range UniversalString code points) and the
1130	    /// single place that decodes them, so the legality check and the text
1131	    /// decoding can never drift apart. It runs once per attribute, before any
1132	    /// display decision and regardless of whether the attribute later renders
1133	    /// as text for a known short name or as '#'-hex for an unknown type:
1134	    /// showing a value as hex must never let an illegal byte or code point
1135	    /// through, and illegal content cannot be dropped or replaced.
1136	    ///
1137	    /// Returns `Ok(Some(text))` for a supported, valid string type, and
1138	    /// `Ok(None)` for any other tag (a legal DER value with no text decoder —
1139	    /// a SEQUENCE, OCTET STRING, … — which the caller renders as '#'-hex). An
1140	    /// empty string value is legal and decodes to empty text. `what` names the
1141	    /// name being checked ("subject"/"issuer") so an error identifies it.
1142	    fn check_attribute_string(value: Tlv, what: &str) -> Result<Option<String>, String> {
1143	        let content = value.content;
1144	        let text = match value.tag {
1145	            TAG_UTF8_STRING => std::str::from_utf8(content)
1146	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
1147	                .to_string(),
1148	            TAG_PRINTABLE_STRING => {
1149	                if !is_printable_string(content) {
1150	                    return Err(format!(
1151	                        "{what} name: PrintableString attribute value contains an illegal \
1152	                         character (only A-Z, a-z, 0-9, space and ' ( ) + , - . / : = ? are \
1153	                         allowed)"
1154	                    ));
1155	                }
1156	                // ASCII-family: after the alphabet check every byte is also
1157	                // its Unicode code point.
