1179	    /// RFC 4514 value escaping; everything above the ASCII control range
1180	    /// (including CJK text) passes through unchanged.
1181	    fn escape_value(value: &str) -> String {
1182	        let mut out = String::with_capacity(value.len());
1183	        let last = value.chars().count().saturating_sub(1);
1184	        for (i, c) in value.chars().enumerate() {
1185	            let at_edge = i == 0 || i == last;
1186	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
