1	//! End-to-end regression tests for X.509 extensions decoding when running
2	//! `chainview inspect <DER-FILE>`.
3	//!
4	//! The extensions field never appears among the five displayed fields, but it
5	//! must be read in full: inspect used to skip the interior of the `[3]`
6	//! wrapper as long as its outer length was intact, so a corrupted extension
7	//! still printed the certificate. These tests pin the fixed contract:
8	//!
9	//! - the field is OPTIONAL and, when present, legal only in an explicit v3
10	//!   certificate (v1 without a version, explicit v1 and v2 must reject it);
11	//! - it may occur at most once; the `[3] EXPLICIT` wrapper contains exactly
12	//!   one non-empty SEQUENCE of extensions;
13	//! - every Extension is a SEQUENCE of OID, optional BOOLEAN, OCTET STRING in
14	//!   that order with nothing appended; the OID must be complete and encoded in
15	//!   minimal form;
16	//! - `critical` omitted means FALSE; an explicit BOOLEAN is accepted only as
17	//!   the DER encoding of TRUE (content exactly FF). Explicit FALSE, other
18	//!   nonzero bytes, empty content and multi-byte contents are all rejected;
19	//! - unknown but legal extension OIDs, critical TRUE and empty OCTET STRING
20	//!   values are all accepted; extension bytes are never interpreted.
21	//! - every extension OID may appear at most once in the list: identity is the
22	//!   complete OID alone, so identical entries or the same OID with different
23	//!   values/critical flags, adjacent or separated, are all rejected with the
24	//!   full dotted OID named; distinct OIDs with identical bodies still coexist.
25	//!
26	//! Every case drives the real binary: success prints exactly the five fixed
27	//! fields (no extension summary is added); failure is exit code 2, completely
28	//! empty stdout and a `chainview: invalid DER certificate: <reason>` stderr
29	//! whose reason locates the problem in the extensions field.
30	
31	use std::fs;
32	use std::path::PathBuf;
33	use std::process::{Command, Output};
34	use std::sync::atomic::{AtomicU64, Ordering};
35	
36	const FIXED_SERIAL: &str = "0E8A4C2F9B17D603";
37	const FIXED_SUBJECT: &str = "CN=example.com";
38	const FIXED_ISSUER: &str = "CN=Test CA";
39	const FIXED_NOT_BEFORE: &str = "2026-01-15T09:30:00Z";
40	const FIXED_NOT_AFTER: &str = "2027-01-15T09:30:00Z";
41	
42	// An unremarkable private extension OID the tool does not recognize.
43	const UNKNOWN_OID: &[u64] = &[1, 2, 3, 4];
44	
45	// ----- Success: legal encodings ---------------------------------------------
46	
47	#[test]
48	fn v3_certificate_without_extensions_is_accepted() {
49	    // Explicit v3 with no [3] field is perfectly legal.
50	    let cert = build_cert(Some(2), &[]);
51	    assert_success(&run_inspect("v3-no-ext", &cert));
52	}
53	
54	#[test]
55	fn v3_certificate_with_one_unknown_extension_is_accepted() {
56	    // Unknown extension types need no allow-list match: a complete,
57	    // minimal-form OID with any OCTET STRING body is accepted.
58	    let ext = extension(UNKNOWN_OID, None, &[0x30, 0x00]);
59	    let cert = build_cert(Some(2), &extensions_field(&ext));
60	    assert_success(&run_inspect("v3-one-ext", &cert));
61	}
62	
63	#[test]
64	fn v3_certificate_with_critical_extension_is_accepted() {
65	    // critical TRUE (01 01 FF) never causes inspect to fail.
66	    let ext = extension(UNKNOWN_OID, Some(true), b"data");
67	    let cert = build_cert(Some(2), &extensions_field(&ext));
68	    assert_success(&run_inspect("v3-critical", &cert));
69	}
70	
71	#[test]
72	fn v3_certificate_with_empty_extension_octet_string_is_accepted() {
73	    // The extnValue OCTET STRING may carry zero bytes; nothing inside it is
74	    // interpreted.
75	    let ext = extension(UNKNOWN_OID, None, &[]);
76	    let cert = build_cert(Some(2), &extensions_field(&ext));
77	    assert_success(&run_inspect("v3-empty-octets", &cert));
78	}
79	
80	#[test]
81	fn v3_certificate_with_multiple_extensions_is_accepted() {
82	    // A non-empty SEQUENCE may hold many extensions, mixing critical and
83	    // non-critical and using multi-byte OID arcs.
84	    let a = extension(&[1, 2, 840, 99999, 7], Some(true), &[0x01]);
85	    let b = extension(&[2, 5, 29, 14], None, &[0x04, 0x02, 0xAA, 0xBB]);
86	    let c = extension(UNKNOWN_OID, None, &[]);
87	    let cert = build_cert(Some(2), &extensions_field(&concat(&[&a, &b, &c])));
88	    assert_success(&run_inspect("v3-multi-ext", &cert));
89	}
