91	#[test]
92	fn v3_extensions_coexist_with_unique_id_fields() {
93	    // issuerUniqueID [1] / subjectUniqueID [2] sit in the same optional tail;
94	    // they must not be mistaken for the [3] extensions field.
95	    let issuer_uid = raw_tlv(0x81, &[0x03], &[0x00, 0xFF, 0xFF]);
96	    let ext = extension(UNKNOWN_OID, None, &[0x00]);
97	    let tail = concat(&[&issuer_uid, &extensions_field(&ext)]);
98	    let cert = build_cert(Some(2), &tail);
99	    assert_success(&run_inspect("v3-unique-id", &cert));
100	}
