102	#[test]
103	fn expired_or_future_certificate_with_extensions_is_still_displayed() {
104	    // Validity is not judged: extensions decode the same on an already
105	    // expired and a not-yet-valid certificate. The two certs intentionally
106	    // differ from the fixed validity dates, so their times are checked
107	    // directly rather than via assert_success.
108	    let ext = extension(UNKNOWN_OID, None, &[0x00]);
109	    let field = extensions_field(&ext);
110	
111	    let expired = build_cert_times(Some(2), &field, b"200115093000Z", b"210115093000Z");
112	    assert_ok_fields(
113	        &run_inspect("ext-expired", &expired),
114	        "2020-01-15T09:30:00Z",
115	        "2021-01-15T09:30:00Z",
116	    );
117	
118	    let future = build_cert_times(Some(2), &field, b"280115093000Z", b"290115093000Z");
119	    assert_ok_fields(
120	        &run_inspect("ext-future", &future),
121	        "2028-01-15T09:30:00Z",
122	        "2029-01-15T09:30:00Z",
123	    );
124	}
