126	// ----- Failure: version rules -----------------------------------------------
127	
128	#[test]
129	fn v1_certificate_without_version_carrying_extensions_is_rejected() {
130	    // No [0] version field means v1; v1 cannot carry extensions.
131	    let ext = extension(UNKNOWN_OID, None, &[0x00]);
132	    let cert = build_cert(None, &extensions_field(&ext));
