152	    let ext = extension(UNKNOWN_OID, None, &[0x00]);
153	    let field = extensions_field(&ext);
154	    let cert = build_cert(Some(2), &concat(&[&field, &field]));
155	    assert_invalid_certificate(&run_inspect("dup-ext", &cert));
156	}
