506	// ----- Assertions / process plumbing ---------------------------------------
507	
508	fn assert_success(out: &Output) {
509	    assert_ok_fields(out, FIXED_NOT_BEFORE, FIXED_NOT_AFTER);
510	}
511	
512	/// Success assertion for certificates whose validity differs from the fixed
513	/// fixture dates: still exit 0, empty stderr, the same five fields in order
514	/// and no extension-related sixth line.
515	fn assert_ok_fields(out: &Output, not_before: &str, not_after: &str) {
516	    assert_eq!(out.status.code(), Some(0), "stderr={}", lossy(&out.stderr));
517	    assert!(out.stderr.is_empty(), "stderr={}", lossy(&out.stderr));
518	    assert_eq!(
519	        lossy(&out.stdout),
520	        format!(
521	            "Subject: {FIXED_SUBJECT}\n\
522	             Issuer: {FIXED_ISSUER}\n\
523	             Serial Number: {FIXED_SERIAL}\n\
524	             Not Before: {not_before}\n\
525	             Not After: {not_after}\n"
526	        )
527	    );
528	}
529	
530	fn assert_invalid_certificate(out: &Output) {
531	    assert_eq!(
532	        out.status.code(),
533	        Some(2),
534	        "stdout={} stderr={}",
535	        lossy(&out.stdout),
536	        lossy(&out.stderr)
537	    );
538	    assert!(
539	        out.stdout.is_empty(),
540	        "stdout must be empty on failure, got: {}",
541	        lossy(&out.stdout)
542	    );
543	    let stderr = lossy(&out.stderr);
544	    const PREFIX: &str = "chainview: invalid DER certificate: ";
545	    assert!(
546	        stderr.starts_with(PREFIX),
547	        "unexpected stderr: {stderr}"
548	    );
549	    let reason = &stderr[PREFIX.len()..];
550	    assert!(
551	        reason.to_ascii_lowercase().contains("extension"),
552	        "error reason must locate the failure in the extensions field: {reason}"
553	    );
554	}
555	
556	/// Duplicate-extension-type failure: exit 2, empty stdout, and the reason
557	/// must say the extension type is duplicated and name the complete dotted
558	/// OID so the conflicting entries can be located.
559	fn assert_duplicate_oid(out: &Output, dotted_oid: &str) {
560	    assert_invalid_certificate(out);
561	    let stderr = lossy(&out.stderr);
562	    let reason = stderr.trim_end();
563	    assert!(
564	        reason.to_ascii_lowercase().contains("duplicate extension type"),
565	        "reason must identify a duplicate extension type: {reason}"
566	    );
567	    assert!(
568	        reason.contains(dotted_oid),
569	        "reason must give the full dotted OID {dotted_oid}: {reason}"
570	    );
571	}
572	
573	fn lossy(bytes: &[u8]) -> String {
574	    String::from_utf8_lossy(bytes).into_owned()
575	}
576	
577	fn run_inspect(tag: &str, data: &[u8]) -> Output {
578	    let cert = TempCert::new(tag, data);
579	    Command::new(env!("CARGO_BIN_EXE_chainview"))
580	        .arg("inspect")
581	        .arg(&cert.path)
582	        .output()
583	        .expect("running chainview")
584	}
585	
586	struct TempCert {
587	    path: PathBuf,
588	}
589	
590	impl TempCert {
591	    fn new(tag: &str, data: &[u8]) -> Self {
592	        static COUNTER: AtomicU64 = AtomicU64::new(0);
593	        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
594	        let path = std::env::temp_dir().join(format!(
595	            "chainview-ext-test-{}-{tag}-{unique}.der",
596	            std::process::id()
597	        ));
598	        fs::write(&path, data).expect("writing temp certificate");
599	        TempCert { path }
600	    }
601	}
602	
603	impl Drop for TempCert {
604	    fn drop(&mut self) {
605	        let _ = fs::remove_file(&self.path);
606	    }
607	}
608	
609	// ----- Certificate / DER construction --------------------------------------
610	
611	/// [3] EXPLICIT wrapping one Extensions SEQUENCE that holds the supplied,
612	/// already-encoded extension items.
613	fn extensions_field(extension_items: &[u8]) -> Vec<u8> {
614	    tlv(0xA3, &tlv(0x30, extension_items))
615	}
616	
617	/// Extension ::= SEQUENCE { extnID OID, critical BOOLEAN DEFAULT FALSE,
618	/// extnValue OCTET STRING }.
619	fn extension(arcs: &[u64], critical: Option<bool>, value: &[u8]) -> Vec<u8> {
620	    let mut content = oid(arcs);
621	    if let Some(flag) = critical {
622	        content.extend_from_slice(&tlv(0x01, &[if flag { 0xFF } else { 0x00 }]));
623	    }
624	    content.extend_from_slice(&tlv(0x04, value));
625	    tlv(0x30, &content)
626	}
627	
628	fn explicit_version(value: u8) -> Vec<u8> {
629	    tlv(0xA0, &tlv(0x02, &[value]))
630	}
631	
632	/// Assemble a complete certificate with fixed visible fields around the
633	/// optional explicit version (`None` = v1 with no version field) and an
634	/// arbitrary, already-encoded TBS tail (usually the extensions field).
635	fn build_cert(version: Option<u8>, tail: &[u8]) -> Vec<u8> {
636	    build_cert_times(version, tail, b"260115093000Z", b"270115093000Z")
637	}
638	
639	fn build_cert_times(
640	    version: Option<u8>,
641	    tail: &[u8],
642	    not_before: &[u8],
643	    not_after: &[u8],
644	) -> Vec<u8> {
645	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
646	    let validity = seq(&concat(&[
647	        &tlv(0x17, not_before),
648	        &tlv(0x17, not_after),
649	    ]));
650	    let subject = simple_cn_name("example.com");
651	    let issuer = simple_cn_name("Test CA");
652	    let spki = spki();
653	
654	    let mut tbs_content = Vec::new();
655	    if let Some(v) = version {
656	        tbs_content.extend_from_slice(&explicit_version(v));
657	    }
658	    tbs_content.extend_from_slice(&serial);
659	    tbs_content.extend_from_slice(&signature_algorithm());
660	    tbs_content.extend_from_slice(&issuer);
661	    tbs_content.extend_from_slice(&validity);
662	    tbs_content.extend_from_slice(&subject);
663	    tbs_content.extend_from_slice(&spki);
664	    tbs_content.extend_from_slice(tail);
665	    let tbs = seq(&tbs_content);
666	
667	    seq(&concat(&[
668	        &tbs,
669	        &signature_algorithm(),
670	        &tlv(0x03, &[0x00]),
671	    ]))
672	}
673	
674	fn signature_algorithm() -> Vec<u8> {
675	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
676	}
677	
678	fn spki() -> Vec<u8> {
679	    let alg = seq(&concat(&[
680	        &oid(&[1, 2, 840, 113549, 1, 1, 1]),
681	        &tlv(0x05, &[]),
682	    ]));
683	    seq(&concat(&[&alg, &tlv(0x03, &[0x00, 0x01, 0x00])]))
684	}
685	
686	fn simple_cn_name(cn: &str) -> Vec<u8> {
687	    let atv = seq(&concat(&[&oid(&[2, 5, 4, 3]), &tlv(0x0C, cn.as_bytes())]));
688	    let rdn = tlv(0x31, &atv);
689	    tlv(0x30, &rdn)
690	}
691	
692	/// TLV with caller-supplied length bytes; used to forge truncated encodings.
693	fn raw_tlv(tag: u8, len_bytes: &[u8], content: &[u8]) -> Vec<u8> {
694	    let mut out = vec![tag];
695	    out.extend_from_slice(len_bytes);
696	    out.extend_from_slice(content);
697	    out
698	}
699	
700	fn oid(arcs: &[u64]) -> Vec<u8> {
701	    assert!(arcs.len() >= 2);
702	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
703	    for &arc in &arcs[2..] {
704	        content.extend_from_slice(&oid_arc(arc));
705	    }
706	    tlv(0x06, &content)
707	}
708	
709	fn oid_arc(mut value: u64) -> Vec<u8> {
710	    let mut out = vec![(value % 128) as u8];
711	    value /= 128;
712	    while value > 0 {
713	        out.push(0x80 | (value % 128) as u8);
714	        value /= 128;
715	    }
716	    out.reverse();
717	    out
718	}
719	
720	fn seq(content: &[u8]) -> Vec<u8> {
721	    tlv(0x30, content)
722	}
723	
724	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
725	    let mut out = vec![tag];
726	    out.extend_from_slice(&der_len(content.len()));
727	    out.extend_from_slice(content);
728	    out
729	}
730	
731	fn der_len(n: usize) -> Vec<u8> {
732	    if n < 0x80 {
733	        vec![n as u8]
734	    } else {
735	        let mut body = Vec::new();
736	        let mut v = n;
737	        while v > 0 {
738	            body.push((v & 0xFF) as u8);
739	            v >>= 8;
740	        }
741	        body.reverse();
742	        let mut out = vec![0x80 | body.len() as u8];
743	        out.extend_from_slice(&body);
744	        out
745	    }
746	}
747	
748	fn concat(parts: &[&[u8]]) -> Vec<u8> {
749	    let mut out = Vec::new();
750	    for part in parts {
751	        out.extend_from_slice(part);
752	    }
753	    out
754	}
