847	#[test]
848	fn truncated_certificate_file_is_rejected() {
849	    // Bytes cut off the tail of an otherwise valid certificate: malformed
850	    // input, same failure contract.
851	    let subject = simple_cn_name("subject.example");
852	    let issuer = simple_cn_name("Test CA");
