860	// ----- DER SET OF ordering inside multi-valued RDNs ------------------------
861	
862	#[test]
863	fn unsorted_subject_multivalued_rdn_is_rejected() {
864	    // O and CN in one RDN, encoded O-first: both members have the same outer
865	    // tag and length, and O's OID arc byte 0x0A is greater than CN's 0x03, so
866	    // the SET OF is not byte-sorted. This must fail as a corrupt certificate
867	    // and name the subject, never be printed or repaired by reordering the
868	    // members (alphabetically "CN" would sort first, which is exactly the
869	    // kind of display-name comparison that must not be used).
870	    let subject = name(&[rdn(&[atv_utf8(O, "y"), atv_utf8(CN, "x")])]);
871	    let issuer = simple_cn_name("Test CA");
872	    let (out, _cert) = run_inspect("bad-order-subject", &build_cert(&subject, &issuer));
873	
874	    assert_invalid_certificate(&out);
875	    let stderr = lossy(&out.stderr);
876	    assert!(
877	        stderr.contains("subject") && stderr.contains("order"),
878	        "reason must name the subject name and the ordering problem: {stderr}"
879	    );
880	}
881	
882	#[test]
883	fn unsorted_issuer_multivalued_rdn_is_rejected() {
884	    // Same violation in the issuer must be reported against the issuer name,
885	    // even though the subject is well-formed.
886	    let subject = simple_cn_name("subject.example");
887	    let issuer = name(&[rdn(&[atv_utf8(O, "y"), atv_utf8(CN, "x")])]);
888	    let (out, _cert) = run_inspect("bad-order-issuer", &build_cert(&subject, &issuer));
889	
890	    assert_invalid_certificate(&out);
891	    let stderr = lossy(&out.stderr);
892	    assert!(
893	        stderr.contains("issuer") && stderr.contains("order"),
894	        "reason must name the issuer name and the ordering problem: {stderr}"
895	    );
896	}
