898	#[test]
899	fn ordering_compares_encoding_content_not_attribute_text() {
900	    // The same unknown OID twice (identical dotted text) with values "b" and
901	    // "a": both complete encodings have equal tag and length, and the first
902	    // value byte 0x62 > 0x61, so "b" before "a" is out of DER order. Sorting
903	    // by attribute name or value text would call these identical or sort the
904	    // same way only by accident; this pins the comparison to encoding bytes.
905	    let subject = name(&[rdn(&[
906	        atv_utf8(&[1, 2, 3, 4], "b"),
